// Moore state machine, one-hot encoded states, combinational transition
// and output logic (no explicit register, product of states and inputs
// directly goes to the next state).
module TopModule(
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);
    reg [3:0] ns;
    always @* begin
        case (state)
            4'b0001: begin ns = 4'b0001; out = 1'b0; end
            4'b0010: begin ns = 4'b0010; out = 1'b0; end
            4'b0100: begin ns = 4'b0100; out = 1'b0; end
            4'b1000: begin ns = 4'b1000; out = 1'b1; end
            default: begin ns = 4'b0001; out = 1'b0; end
        endcase
    end
    assign next_state = ns;
endmodule

// Moore state machine, one input, one output, four states, one-hot
// encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000. Derive state
// transition and output logic equations by inspection (the combinational
// logic portion, the state register is explicitly synthesized).
module TopModule(
    input in,
    input [3:0] state,
    output reg [3:0] next_state,
    output reg out
);
    always @(*) begin
        case (state)
            4'b0001: begin next_state = in ? 4'b0010 : 4'b0001; out = 1'b0; end
            4'b0010: begin next_state = in ? 4'b0100 : 4'b0010; out = 1'b0; end
            4'b0100: begin next_state = in ? 4'b0001 : 4'b0100; out = 1'b0; end
            4'b1000: begin next_state = in ? 4'b0010 : 4'b0100; out = 1'b1; end
        endcase
    end
endmodule

