module TopModule(
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);
    wire [3:0] ns;
    assign ns = state[2] ? (state[0] ? 4'b0001 : 4'b0010) : (state[0] ? 4'b0100 : 4'b1000);
